package com.hostelfind.controller;
import com.hostelfind.dto.StatusRequest; import com.hostelfind.model.*; import com.hostelfind.repository.ItemRepository; import com.hostelfind.service.*; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
/** Admin routes: secure with Spring Security before production deployment. */
@RestController @RequestMapping("/api/admin") @CrossOrigin(origins="*") public class AdminController { private final ItemRepository items; private final ItemService itemService; private final ClaimService claimService; public AdminController(ItemRepository items,ItemService itemService,ClaimService claimService){this.items=items;this.itemService=itemService;this.claimService=claimService;} @GetMapping("/items") public List<Item> allItems(){return items.findAllByOrderByDateDesc();} @PatchMapping("/items/{id}/status") public Item status(@PathVariable Long id,@Valid @RequestBody StatusRequest body){Item i=itemService.one(id);i.setStatus(body.status());return items.save(i);}@GetMapping("/claims/item/{itemId}") public List<Claim> claims(@PathVariable Long itemId){return claimService.forItem(itemId);}@PatchMapping("/claims/{id}") public Claim updateClaim(@PathVariable Long id,@RequestParam ClaimStatus status){return claimService.update(id,status);} }
